import json
from datetime import datetime
from pathlib import Path

import pandas as pd

OUT_PARQUET = Path('/app/merged_users.parquet')
OUT_CONFLICTS = Path('/app/conflicts.json')
SOURCES = ['source_a', 'source_b', 'source_c']


def missing(value):
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def clean_text(value):
    if missing(value):
        return None
    value = str(value).strip()
    return value if value else None


def normalize_date(value):
    value = clean_text(value)
    if value is None:
        return None
    parsed = pd.to_datetime(value, errors='coerce')
    if pd.isna(parsed):
        raise ValueError(f'Invalid date: {value!r}')
    return parsed.strftime('%Y-%m-%d')


def normalize_status(value):
    if missing(value):
        return None
    if isinstance(value, bool):
        return 'active' if value else 'inactive'
    text = str(value).strip().lower()
    if text in {'true', '1', 'yes', 'y', 'active'}:
        return 'active'
    if text in {'false', '0', 'no', 'n', 'inactive'}:
        return 'inactive'
    return text


def read_source(name):
    if name == 'source_a':
        rows = json.loads(Path('/data/source_a/users.json').read_text())
        frame = pd.DataFrame(rows)
        mapping = {'id': 'user_id', 'full_name': 'name', 'email': 'email',
                   'registration_date': 'created_date', 'status': 'status'}
    elif name == 'source_b':
        frame = pd.read_csv('/data/source_b/users.csv')
        mapping = {'user_id': 'user_id', 'name': 'name', 'email_address': 'email',
                   'created_at': 'created_date', 'is_active': 'status'}
    else:
        frame = pd.read_parquet('/data/source_c/users.parquet')
        mapping = {'userId': 'user_id', 'userName': 'name', 'email': 'email',
                   'joined': 'created_date', 'active': 'status'}
    frame = frame.rename(columns=mapping)
    for col in ['user_id', 'name', 'email', 'created_date', 'status']:
        if col not in frame.columns:
            frame[col] = None
    normalized = []
    for _, row in frame.iterrows():
        uid = row['user_id']
        if missing(uid):
            continue
        uid = int(uid)
        normalized.append({
            'user_id': uid,
            'name': clean_text(row['name']),
            'email': clean_text(row['email']),
            'created_date': normalize_date(row['created_date']),
            'status': normalize_status(row['status']),
        })
    return normalized


records_by_source = {source: read_source(source) for source in SOURCES}
by_user = {}
for source in SOURCES:
    for record in records_by_source[source]:
        by_user.setdefault(record['user_id'], {})[source] = record

fields = ['name', 'email', 'created_date', 'status']
merged = []
conflicts = []

for user_id in sorted(by_user):
    source_records = by_user[user_id]
    result = {'user_id': user_id}
    for field in fields:
        values = {source: source_records[source].get(field)
                  for source in SOURCES if source in source_records}
        distinct = set(values.values()) - {None}
        if len(distinct) > 1:
            report_values = {source: values[source] for source in SOURCES
                             if source in values and values[source] is not None}
            selected = next((values[source] for source in SOURCES
                             if source in values and values[source] is not None), None)
            conflicts.append({
                'user_id': user_id,
                'field': field,
                'values': report_values,
                'selected': selected,
            })
        result[field] = next((values[source] for source in SOURCES
                              if source in values and values[source] is not None), None)
    merged.append(result)

output = pd.DataFrame(merged, columns=['user_id', 'name', 'email', 'created_date', 'status'])
output['user_id'] = output['user_id'].astype('int64')
for col in ['name', 'email', 'created_date', 'status']:
    output[col] = output[col].astype('string')
output.to_parquet(OUT_PARQUET, engine='pyarrow', index=False)
OUT_CONFLICTS.write_text(json.dumps({
    'total_conflicts': len(conflicts),
    'conflicts': conflicts,
}, indent=2) + '\n')
print(f'wrote {len(output)} users and {len(conflicts)} conflicts')
